const x=$json;
const ops=['cart_view','cart_add','cart_update','cart_remove','cart_clear'];
if(!ops.includes(x.operation)) throw new Error('cart_invalid_operation');
if(typeof x.customer_id!=='string'||!x.customer_id.trim()) throw new Error('cart_missing_customer');
if(!['facebook','whatsapp','instagram','internal'].includes(x.channel)) throw new Error('cart_invalid_channel');

if(['cart_add','cart_update'].includes(x.operation)){
  if(x.quantity==null || !Number.isInteger(x.quantity) || x.quantity<1 || x.quantity>99)
    throw new Error('cart_invalid_quantity');
  if(!x.product_id && !x.variation_id && !x.sku)
    throw new Error('cart_missing_product_reference');
}
if(x.operation==='cart_remove' && !x.product_id && !x.variation_id && !x.sku)
  throw new Error('cart_missing_product_reference');

return [{json:{...x,store_id:x.store_id||'default',
  idempotency_key:x.idempotency_key||x.action_id||`${x.customer_id}:${x.operation}`}}];

const x=$('Validate Cart Request').first().json;
const row=$input.all().map(i=>i.json)[0]||{};
return [{json:{
  operation:x.operation,
  customer_id:x.customer_id,
  channel:x.channel,
  store_id:x.store_id,
  product_id:x.product_id||null,
  variation_id:x.variation_id||null,
  sku:x.sku||null,
  quantity:x.quantity??null,
  idempotency_key:x.idempotency_key,
  action_id:x.action_id||x.idempotency_key,
  existing_cart_reference:row.cart_reference||null,
  // Raw cart token is deliberately NOT passed through WF-12.
  cart_token_resolution:'internal_wf20_only'
}}];

const input=$('Prepare WF-20 Cart Request').first().json;
const r=$json;
if(r.commerce_status==='unavailable'){
  return [{json:{
    success:false,operation:input.operation,customer_id:input.customer_id,
    commerce_status:'unavailable',verified:false,
    error:{code:'COMMERCE_UNAVAILABLE',transactional_action_blocked:true,
      fallback:'preserve_purchase_intent_and_continue_kb_sales_conversation'}
  }}];
}
const success=Boolean(r.success);
return [{json:{
  success,operation:input.operation,customer_id:input.customer_id,
  commerce_status:r.commerce_status||'available',
  verified:Boolean(r.verified && success),
  cart:r.cart||null,
  error:r.error||null,
  idempotency_key:input.idempotency_key
}}];

const x=$json;
if(x.success && !x.verified) throw new Error('cart_success_without_verification');
if(x.success && x.commerce_status!=='available') throw new Error('cart_success_without_live_commerce');
if(x.operation==='cart_view' && x.success && !x.cart) throw new Error('cart_view_missing_state');
return [{json:x}];
